// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint64 newTime) public {
        vm.assume(actor != address(0));

        uint256 amount = 10 ether;

        vm.deal(actor, amount);

        uint64 minT = uint64(block.timestamp) + 1;
        uint64 maxT = minT + 1000000;
        uint64 t = newTime;
        if (t < minT) t = minT;
        if (t > maxT) t = maxT;

        vm.warp(t);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");

        if (ok) {
            assertTrue(c.pastBlockTime() == uint256(t));
        } else {
            assertTrue(c.pastBlockTime() <= uint256(t));
        }
    }
}
